INSERT INTO public.career_paths (domain, title, slug, description, overview, trajectory, salary_entry, salary_mid, salary_senior, perks, impact, exposure, eligibility, skills_needed, upsc_skill_mapping, difficulty_rating, growth_rate, courses, certifications, portfolio_projects, launchpad_weeks, estimated_cost, how_to_apply, youtube_links, podcast_links, professional_associations) VALUES

-- =============================================
-- DOMAIN 1: Policy, Governance & Public Affairs
-- =============================================

('Policy, Governance & Public Affairs', 'Policy Research Analyst', 'policy-research-analyst',
'Conduct research and analysis to inform government and organizational policy decisions.',
'Policy Research Analysts are the intellectual backbone of think tanks, government bodies, and NGOs. They synthesize complex data, analyze legislation, and produce actionable research that shapes how governments and organizations make decisions. Your UPSC background is a direct competitive advantage — you already understand governance structures, constitutional frameworks, and policy history better than most candidates.',
'[{"stage":"Entry","title":"Research Associate","years":"0-2","salary":"₹4-7 LPA","responsibilities":["Literature reviews and data collection","Drafting policy briefs and memos","Supporting senior analysts on projects","Maintaining research databases"]},{"stage":"Mid","title":"Policy Analyst","years":"2-5","salary":"₹7-14 LPA","responsibilities":["Leading research projects independently","Publishing reports and policy papers","Stakeholder consultations","Presenting findings to senior leadership"]},{"stage":"Senior","title":"Senior Policy Analyst","years":"5-8","salary":"₹14-22 LPA","responsibilities":["Setting research agenda","Managing junior analysts","Media engagement and public commentary","Advisory roles for government committees"]},{"stage":"Leadership","title":"Research Director / Fellow","years":"8+","salary":"₹22-40 LPA","responsibilities":["Organizational strategy","Fundraising and partnerships","Building research teams","Policy advocacy at national level"]}]',
'₹4-7 LPA', '₹7-14 LPA', '₹22-40 LPA',
ARRAY['Health insurance', 'Conference travel', 'Publication opportunities', 'Flexible work', 'Sabbatical leave'],
'Shape legislation, influence budget allocations, and inform decisions that affect millions of citizens. Your analysis can lead to better healthcare policy, smarter urban planning, or more effective education programs.',
'Work with senior bureaucrats, ministers, and international development organizations. Get published in reputed journals. Attend global policy conferences.',
'Any graduate degree. Masters in Public Policy, Economics, Political Science, or Social Sciences preferred. Strong writing skills essential.',
ARRAY['Policy analysis', 'Quantitative research', 'Report writing', 'Statistical analysis', 'Stakeholder management', 'Public speaking', 'Data visualization'],
'Your UPSC preparation gave you a comprehensive understanding of Indian governance, constitutional law, and public administration. Essay writing and GS paper answers translate directly to policy brief writing. Your knowledge of economic surveys, budget documents, and five-year plans is exactly what policy analysts study for years.',
3, 'High - growing demand for evidence-based policy',
'[{"name":"Policy Analysis for the Real World","provider":"Oxford University (Coursera)","url":"https://www.coursera.org/learn/policy-analysis","cost":"Free audit","duration":"6 weeks"},{"name":"Public Policy and Social Research","provider":"The Hindu Centre (India)","url":"https://www.thehinducentre.com","cost":"₹15,000","duration":"3 months"},{"name":"Data Analysis for Social Scientists","provider":"MIT OpenCourseWare","url":"https://ocw.mit.edu","cost":"Free","duration":"Self-paced"}]',
ARRAY['Certificate in Public Policy (CPP)', 'Postgraduate Diploma in Public Policy (IIPA)', 'GIS Certification for policy mapping'],
ARRAY['Write 3 policy briefs on current issues (healthcare, education, environment)', 'Create a data visualization dashboard on a public dataset', 'Publish one op-ed in a national newspaper'],
'[{"week":1,"title":"Foundation & Orientation","tasks":["Read 5 policy briefs from PRS Legislative Research","Join CUTS International and CPR mailing lists","Set up Google Scholar alerts for your policy areas","Draft your first 500-word policy memo on a current issue"]},{"week":2,"title":"Research Methods","tasks":["Complete free course: Policy Analysis Fundamentals on Coursera","Learn to read and interpret government data from data.gov.in","Practice writing executive summaries","Study 3 model policy papers from NITI Aayog"]},{"week":3,"title":"Target Organizations","tasks":["List 20 think tanks and policy orgs in India","Research CPR, NCAER, IDFC Institute, CSDS","Identify 3 entry-level openings","Connect with 5 policy analysts on LinkedIn"]},{"week":4,"title":"Build Your Writing Portfolio","tasks":["Write a 1500-word policy paper on a GS topic you know well","Get feedback from academic contacts","Create a simple personal website or LinkedIn portfolio","Apply to PRS Legislative Research for research associate roles"]},{"week":5,"title":"Network Actively","tasks":["Attend one webinar or policy event","Email 3 policy researchers for informational interviews","Join policy-focused Slack/Discord communities","Follow up on all LinkedIn connections"]},{"week":6,"title":"Data Skills","tasks":["Learn basic Excel/Python for data analysis","Practice with India census data","Create one chart-heavy infographic on a policy topic","Upload to LinkedIn or Medium"]},{"week":7,"title":"Applications","tasks":["Apply to 10+ organizations (think tanks, NGOs, government bodies)","Tailor each application to the org mission","Prepare 3 writing samples","Ask 2 people for recommendations"]},{"week":8,"title":"Interview Prep","tasks":["Research the interviewing organization deeply","Prepare answers to: Why policy? What current issue concerns you most?","Practice policy case analysis","Mock interview with a friend or mentor"]},{"week":9,"title":"Expand Network","tasks":["Attend a Delhi Policy Group or similar event","Introduce yourself to 2 senior researchers","Share your policy paper publicly","Apply to fellowship programs (LAMP, CASI)"]},{"week":10,"title":"Deepen Domain Expertise","tasks":["Choose a specialization: health, education, urban, environment","Read 2 books in that domain","Subscribe to relevant government newsletters","Draft a domain-specific research question"]},{"week":11,"title":"Digital Presence","tasks":["Optimize LinkedIn with policy keywords","Write one LinkedIn article on a policy topic","Follow up with all pending applications","Ask for feedback from recent interviews"]},{"week":12,"title":"Launch Week","tasks":["Finalize your portfolio website","Send thank-you notes to everyone who helped","Apply to 5 more organizations","Set 3-month career goals and track progress"]}]',
'₹5,000-25,000 (mainly courses and conference fees)',
'Apply directly to think tanks (CPR, NCAER, PRS), NGOs (OXFAM India, CRY), and government research bodies. Fellowship programs like LAMP Fellowship and Takshashila are excellent entry points.',
'[{"title":"India Policy Podcast","url":"https://www.youtube.com/@indiapolicypodcast","channel":"India Policy Podcast"},{"title":"Takshashila Institution Lectures","url":"https://www.youtube.com/@takshashilainstitution","channel":"Takshashila Institution"}]',
'[{"title":"The Seen and the Unseen","url":"https://seenunseen.in","host":"Amit Varma"},{"title":"Everything is Everything","url":"https://everything.substack.com","host":"Shruti Rajagopalan"}]',
ARRAY['Takshashila Institution Alumni Network', 'IIPA (Indian Institute of Public Administration)', 'Centre for Policy Research', 'PRS Legislative Research']),

('Policy, Governance & Public Affairs', 'Legislative/Parliamentary Research Associate', 'legislative-research-associate',
'Support MPs and parliamentary committees with research, drafting, and legislative analysis.',
'Legislative Research Associates support members of Parliament and their offices with research on bills, budget analysis, constituency issues, and policy positions. PRS Legislative Research is the most prominent organization in this space in India. This role puts you at the center of lawmaking.',
'[{"stage":"Entry","title":"Research Associate","years":"0-2","salary":"₹5-8 LPA","responsibilities":["Bill summaries and legislative tracking","Background research for MPs","Drafting speeches and notes","Parliamentary question research"]},{"stage":"Mid","title":"Senior Research Associate","years":"2-5","salary":"₹8-15 LPA","responsibilities":["Leading bill analysis projects","Committee work support","Media engagement","Training junior associates"]},{"stage":"Senior","title":"Research Manager","years":"5-8","salary":"₹15-25 LPA","responsibilities":["Managing research teams","Direct MP advisory work","Published analysis and reports","Public testimony"]},{"stage":"Leadership","title":"Director of Research","years":"8+","salary":"₹25-45 LPA","responsibilities":["Organizational leadership","Fundraising","Policy advocacy","Building institutional reputation"]}]',
'₹5-8 LPA', '₹8-15 LPA', '₹25-45 LPA',
ARRAY['Proximity to power', 'Published work', 'Travel for field research', 'Flexible hours', 'Prestige'],
'Shape the legislative process at the national level. Your research can directly influence how laws are written and amended.',
'Work directly with elected representatives. Deep exposure to the legislative process, committee hearings, and parliamentary procedure.',
'Any graduate degree. Background in political science, law, or public policy preferred. Excellent written English essential.',
ARRAY['Legislative drafting', 'Legal research', 'Report writing', 'Parliamentary procedure knowledge', 'Data analysis', 'Communication skills'],
'UPSC preparation provides deep knowledge of Indian polity, constitutional provisions, and parliamentary procedures — all directly applicable. Your essay writing skills and ability to synthesize complex information are exactly what legislative research demands.',
3, 'Stable with growth',
'[{"name":"Indian Parliamentary System","provider":"Lok Sabha Secretariat","url":"https://loksabha.nic.in","cost":"Free","duration":"Self-paced"},{"name":"Legal Research & Writing","provider":"National Law School (NLSIU)","url":"https://www.nls.ac.in","cost":"₹10,000","duration":"2 months"}]',
ARRAY['Certificate in Parliamentary Practice (Commonwealth Parliamentary Association)'],
ARRAY['Analysis of 5 recent bills with constitutional implications', 'Budget speech analysis for last 3 years', 'Constituency development report template'],
'[{"week":1,"title":"Understand the Legislative Landscape","tasks":["Read PRS Legislative Research briefs daily","Study recent Lok Sabha and Rajya Sabha sessions","Read Constitution Articles 79-123","Create a tracker of active bills"]},{"week":2,"title":"Master Bill Analysis","tasks":["Read 10 PRS bill summaries","Draft your own bill summary for a recent bill","Compare your draft with PRS version","Study the legislative process flowchart"]},{"week":3,"title":"Budget Research Skills","tasks":["Study Union Budget documents","Learn to read Expenditure Budget Volumes","Practice budget analysis for one ministry","Create a budget explainer for a non-expert"]},{"week":4,"title":"Apply to PRS and Similar Orgs","tasks":["Apply to PRS Legislative Research","Apply to Lok Sabha Secretariat internship","Apply to Rajya Sabha Research Fellowship","Contact MPs offices directly"]},{"week":5,"title":"Parliamentary Procedure Deep Dive","tasks":["Read Rules of Procedure for Lok Sabha","Study Question Hour, Zero Hour, Calling Attention","Create a cheatsheet of parliamentary instruments","Watch Parliament sessions on Sansad TV"]},{"week":6,"title":"Network with Legislative Professionals","tasks":["LinkedIn outreach to PRS alumni","Attend a parliamentary committee hearing (open to public)","Connect with political journalists","Follow up on applications"]},{"week":7,"title":"Legal Research Skills","tasks":["Learn to use SCC Online and Manupatra","Research landmark SC judgments on constitutional issues","Practice note-writing for legal research","Study legislative intent in bill statements"]},{"week":8,"title":"Writing Portfolio","tasks":["Write a comprehensive bill analysis (2000 words)","Write a constituency issue brief","Draft a parliamentary question on a current issue","Compile portfolio"]},{"week":9,"title":"Interviews and Follow-ups","tasks":["Prepare for PRS interview process","Practice case-study style questions","Research the organization mission and recent work","Prepare 3 samples of written work"]},{"week":10,"title":"Expand Scope","tasks":["Research state legislature opportunities","Apply to state legislative research bodies","Look at Election Commission research roles","Explore Vidhi Centre for Legal Policy"]},{"week":11,"title":"Digital Skills","tasks":["Learn basic data visualization","Create an infographic on a parliamentary statistic","Improve LinkedIn profile","Write a Medium article on a legislative topic"]},{"week":12,"title":"Launch","tasks":["Finalize all applications","Follow up with all contacts","Prepare negotiation talking points for salary","Set 6-month goals"]}]',
'₹3,000-10,000 (minimal investment needed)',
'Apply directly to PRS Legislative Research, Lok Sabha Secretariat Fellowship, and Rajya Sabha Research Fellowship. Also approach MPs offices with tailored letters.',
'[{"title":"PRS Legislative Research","url":"https://www.youtube.com/@PRSLegislativeResearch","channel":"PRS Legislative Research"},{"title":"Sansad TV","url":"https://www.youtube.com/@SansadTV","channel":"Sansad TV"}]',
'[{"title":"The Pragati Podcast","url":"https://takshashila.org.in/research/pragati-podcast","host":"Pranay Kotasthane"}]',
ARRAY['PRS Legislative Research', 'Commonwealth Parliamentary Association India', 'Lok Sabha Secretariat']),

('Policy, Governance & Public Affairs', 'Government Relations / Public Affairs Manager', 'govt-relations-public-affairs',
'Manage relationships between corporations or NGOs and government bodies, regulators, and policymakers.',
'Government Relations professionals are the bridge between the private sector and the government. Companies need people who understand how policy is made, how regulators think, and how to navigate complex bureaucratic processes. Your UPSC background makes you exceptionally credible in this role.',
'[{"stage":"Entry","title":"GR Executive","years":"0-2","salary":"₹6-10 LPA","responsibilities":["Regulatory tracking","Drafting position papers","Attending policy consultations","Internal briefings"]},{"stage":"Mid","title":"GR Manager","years":"2-5","salary":"₹10-20 LPA","responsibilities":["Managing regulatory filings","Leading government engagement","Industry association work","Crisis communication"]},{"stage":"Senior","title":"Senior GR Manager / Director","years":"5-8","salary":"₹20-40 LPA","responsibilities":["C-suite advisory","Strategic positioning","Coalition building","Media advocacy"]},{"stage":"Leadership","title":"VP / Head of Public Affairs","years":"8+","salary":"₹40-80 LPA","responsibilities":["Board-level advisory","National regulatory strategy","Industry leadership","Government partnerships"]}]',
'₹6-10 LPA', '₹10-20 LPA', '₹40-80 LPA',
ARRAY['Corporate benefits package', 'High visibility', 'Travel', 'Senior stakeholder access', 'Stock options at large firms'],
'Help shape regulatory environments that affect entire industries. Good GR work can prevent bad regulation and enable innovation.',
'Access to CXOs, senior bureaucrats, ministers, and industry associations. High visibility across government and industry.',
'Any graduate degree. MBA or public policy background preferred. Knowledge of regulatory frameworks essential.',
ARRAY['Stakeholder management', 'Policy analysis', 'Communication', 'Strategic thinking', 'Negotiation', 'Regulatory knowledge', 'Report writing'],
'UPSC preparation gives you an unmatched understanding of how the Indian government works — ministries, regulatory bodies, legislative process. This insider knowledge is exactly what companies pay premium salaries for in GR roles.',
3, 'Very high - every major company needs GR',
'[{"name":"Corporate Political Strategy","provider":"IIM Ahmedabad Executive Education","url":"https://www.iima.ac.in/executive-education","cost":"₹50,000","duration":"2 days"},{"name":"Regulatory Affairs Certificate","provider":"NASSCOM","url":"https://www.nasscom.in","cost":"₹20,000","duration":"1 month"}]',
ARRAY['Certificate in Government Relations (FICCI)', 'Public Affairs Professional Certification'],
ARRAY['Regulatory impact assessment for a new bill in your industry', 'Position paper on a current policy issue', 'Stakeholder mapping exercise'],
'[{"week":1,"title":"Understand the GR Landscape","tasks":["Research top 10 companies with large GR teams (Reliance, Tata, Google India)","Read about FICCI, CII, ASSOCHAM roles","Study recent regulatory changes in telecom, fintech, pharma","Map key ministries to industries"]},{"week":2,"title":"Build Industry Knowledge","tasks":["Pick 2 focus industries (tech, healthcare, energy)","Subscribe to industry newsletters","Read regulatory filings of major companies","Understand MCA, SEBI, TRAI, RBI regulatory roles"]},{"week":3,"title":"Develop Positioning","tasks":["Update LinkedIn to reflect GR interest","Highlight UPSC/governance knowledge prominently","Connect with GR professionals on LinkedIn","Request 3 informational interviews"]},{"week":4,"title":"Writing Skills","tasks":["Draft a position paper on a regulatory issue","Write a regulatory update brief","Study government consultation documents","Practice writing executive memos"]},{"week":5,"title":"Industry Association Entry","tasks":["Apply for associate membership in CII or FICCI","Attend one industry event","Volunteer to write for their newsletter","Network at the event"]},{"week":6,"title":"Target Companies","tasks":["List 20 companies with GR teams","Research their current regulatory challenges","Tailor applications to each company","Apply to GR Executive roles"]},{"week":7,"title":"Stakeholder Mapping","tasks":["Learn stakeholder mapping methodology","Create a sample stakeholder map for a fictional company","Practice identifying key influencers","Study lobbying disclosure norms in India"]},{"week":8,"title":"Interview Preparation","tasks":["Prepare for policy knowledge questions","Practice case studies on regulatory scenarios","Research interviewing companies deeply","Prepare questions to ask the interviewer"]},{"week":9,"title":"Consulting as Alternative","tasks":["Research GR consulting firms (KPMG, EY, PwC public policy arms)","Apply to consulting firms as an entry point","Prepare for consulting-style case interviews","Network with consulting alumni"]},{"week":10,"title":"Build Relationships","tasks":["Attend one government consultation as a stakeholder","Write a comment on a draft regulation","Share analysis publicly on LinkedIn","Connect with regulatory journalists"]},{"week":11,"title":"Digital Presence","tasks":["Write 2 LinkedIn articles on regulatory topics","Build following among GR professionals","Engage on policy Twitter/LinkedIn","Update portfolio"]},{"week":12,"title":"Close the Loop","tasks":["Follow up on all applications","Prepare salary negotiation strategy","Finalize all writing samples","Set 6-month goals for first GR role"]}]',
'₹10,000-30,000 (industry events, courses)',
'Apply directly to Corporate Affairs / Government Relations departments of large companies. Also approach GR consulting firms like APCO Worldwide, Ketchum Sampark, and ICCO. Industry associations (FICCI, CII) also hire GR executives.',
'[{"title":"How Government Affairs Works","url":"https://www.youtube.com/watch?v=example","channel":"Harvard Kennedy School"},{"title":"Regulatory Policy in India","url":"https://www.youtube.com/watch?v=example2","channel":"Gateway House"}]',
'[{"title":"Policy & Purpose Podcast","url":"https://policypurpose.com","host":"Various GR professionals"}]',
ARRAY['FICCI', 'CII', 'ASSOCHAM', 'Public Affairs Forum of India (PAFI)']),

('Policy, Governance & Public Affairs', 'Development Sector Program Manager', 'development-sector-program-manager',
'Lead and manage development programs in NGOs, international development organizations, and foundations.',
'Development sector program managers design, implement, and evaluate programs that address social challenges — poverty, education, health, gender, environment. Organizations like UN agencies, World Bank, bilateral aid agencies, and large NGOs need people who combine analytical skills with on-ground project management.',
'[{"stage":"Entry","title":"Program Associate","years":"0-2","salary":"₹4-8 LPA","responsibilities":["Field data collection","Program monitoring","Report writing","Stakeholder coordination"]},{"stage":"Mid","title":"Program Manager","years":"2-5","salary":"₹8-18 LPA","responsibilities":["Program design and implementation","Budget management","Team leadership","Donor reporting"]},{"stage":"Senior","title":"Senior Program Manager","years":"5-8","salary":"₹18-30 LPA","responsibilities":["Portfolio management","Fundraising","Partner management","Impact evaluation"]},{"stage":"Leadership","title":"Country Director / Program Director","years":"8+","salary":"₹30-70 LPA","responsibilities":["Strategic direction","Board engagement","National partnerships","Policy influence"]}]',
'₹4-8 LPA', '₹8-18 LPA', '₹30-70 LPA',
ARRAY['Mission-driven work', 'International travel', 'Professional development budget', 'Work from field locations', 'Strong alumni networks'],
'Directly improve lives through programs in education, health, livelihoods, and governance. Your work is measurable in people helped.',
'Work with international organizations, senior government officials, and community leaders. Travel extensively.',
'Any graduate degree. Background in social sciences, development studies, or public policy preferred. Field experience valued.',
ARRAY['Program management', 'M&E (monitoring and evaluation)', 'Proposal writing', 'Budget management', 'Stakeholder engagement', 'Report writing', 'Data analysis'],
'UPSC preparation gave you deep knowledge of social sector schemes (MGNREGA, PM-KISAN, NHM), India''s development challenges, and government structures. Your understanding of districts, blocks, and village-level governance is exactly what development organizations need.',
3, 'High - sector growing with more international funding',
'[{"name":"Monitoring and Evaluation of Public Sector Programs","provider":"World Bank Open Learning","url":"https://olc.worldbank.org","cost":"Free","duration":"4 weeks"},{"name":"Development Impact Evaluation","provider":"J-PAL (MIT)","url":"https://www.povertyactionlab.org/research-resources/training","cost":"Free","duration":"Self-paced"},{"name":"Project Management for Development","provider":"PMD Pro","url":"https://www.pmdpro.org","cost":"$300","duration":"Self-paced"}]',
ARRAY['PMD Pro Certification', 'Certificate in M&E', 'PRINCE2 Foundation'],
ARRAY['Design a theory of change for a social program', 'Write a grant proposal for a community initiative', 'Create an M&E framework for an existing scheme'],
'[{"week":1,"title":"Map the Development Ecosystem","tasks":["Research key organizations: UNICEF India, UNDP India, Oxfam India, CRY, Pratham","Understand bilateral vs multilateral vs NGO roles","Subscribe to DevEx and India Development Review","Create a target list of 20 organizations"]},{"week":2,"title":"Learn M&E Fundamentals","tasks":["Complete World Bank M&E course (free)","Understand Theory of Change, LogFrame","Practice designing indicators for a program","Read an evaluation report from 3ie"]},{"week":3,"title":"Proposal Writing","tasks":["Read 3 successful grant proposals","Draft a concept note for a hypothetical program","Learn to write SMART objectives","Research donor priorities (USAID, FCDO, Gates Foundation)"]},{"week":4,"title":"Applications Round 1","tasks":["Apply to 10 development organizations","Focus on Teach For India, Pratham, Aga Khan Foundation","Prepare a tailored cover letter highlighting UPSC background","Update LinkedIn with development focus"]},{"week":5,"title":"Field Skills","tasks":["Volunteer 1-2 days with a local NGO","Learn participatory rural appraisal methods","Practice interviewing community members","Document your field experience"]},{"week":6,"title":"Financial Management","tasks":["Learn basics of development project budgets","Understand donor financial reporting requirements","Practice creating a simple project budget","Study FCRA compliance for Indian NGOs"]},{"week":7,"title":"Technical Writing","tasks":["Write a situation analysis for a development issue","Practice writing beneficiary impact stories","Create a project one-pager","Build a portfolio of 3 writing samples"]},{"week":8,"title":"Networking","tasks":["Attend India Development Review events","Connect with development professionals on LinkedIn","Reach out to alumni from IRMA, TISS, XIMB","Request 3 informational interviews"]},{"week":9,"title":"UN and International Orgs","tasks":["Register on UN Careers portal (careers.un.org)","Apply to UNV (UN Volunteer) programs","Research UNDP India, UNICEF India openings","Prepare for UN interview competencies"]},{"week":10,"title":"Specialization","tasks":["Choose a thematic area: education, health, gender, livelihoods","Deep-read 2 reports in that area","Connect with domain experts","Apply to specialized organizations"]},{"week":11,"title":"Interview Prep","tasks":["Prepare STAR-method answers for behavioral questions","Practice program design case studies","Research interviewing organizations deeply","Prepare portfolio presentation"]},{"week":12,"title":"Launch","tasks":["Final applications push","Follow up on all pending applications","Request feedback from interviewers","Set 6-month learning goals for new role"]}]',
'₹5,000-20,000 (certifications, events)',
'Apply directly to UNICEF India, UNDP India, Oxfam India, CRY, Pratham, Teach For India. Also register on UN Careers, Idealist, and Devex job boards.',
'[{"title":"India Development Review","url":"https://www.youtube.com/@IndiaDevelopmentReview","channel":"IDR"},{"title":"J-PAL Research Talks","url":"https://www.youtube.com/@JPAL_org","channel":"J-PAL"}]',
'[{"title":"Governance Now Podcast","url":"https://www.governancenow.com/podcast","host":"Governance Now"},{"title":"IDR Podcast","url":"https://idronline.org/podcast","host":"India Development Review"}]',
