ifications","tasks":["Register for CFA ESG Certificate exam","Study GRI Standards in depth","Research LEED Associate certification","Begin formal certification preparation"]},{"week":10,"title":"Industry Deep Dives","tasks":["Choose 2 industries: energy, manufacturing, finance, agriculture","Study their specific sustainability challenges","Research regulatory requirements in each sector","Build domain expertise"]},{"week":11,"title":"Network and Events","tasks":["Attend Climate Change Leadership events","Connect with FICCI Green Business Centre","Join CII-Sohrabji Godrej Green Business Centre network","Build profile at sustainability events"]},{"week":12,"title":"Launch","tasks":["Accept best offer or consulting project","Continue ESG certification","Join sustainability professional network","Set 6-month learning goals"]}]',
